d post types.'=>'Metabox dan kolom shortlink hanya akan muncul di jenis pos yang dipilih.','Select all logs'=>'Pilih semua log','Select log entry %d'=>'Pilih entri log %d','Dynamic Redirect'=>'Pengalihan Dinamis','Redirected by %s'=>'Diarahkan oleh %s','Could not fetch target URL details.'=>'Tidak dapat mengambil rincian URL target.','Create a Shortlink'=>'Buat Shortlink','Reset Yesterday\'s Analytics'=>'Reset Analitik Kemarin','Reset Last 30 Days Analytics'=>'Reset Analitik 30 Hari Terakhir','Reset Last Month\'s Analytics'=>'Reset Analitik Bulan Lalu','Reset Last 2 Years Analytics'=>'Reset Analitik 2 Tahun Terakhir','Reset Custom Range Analytics'=>'Reset Analitik Rentang Kustom','Reset All Time Analytics'=>'Reset Analitik Sepanjang Waktu','Showing data from %1$s to %2$s'=>'Menampilkan data dari %1$s hingga %2$s','Analytics updated. Total clicks: %1$s. Unique visitors: %2$s. Days with clicks: %3$s. Average per click day: %4$s.'=>'Analitik diperbarui. Total klik: %1$s. Pengunjung unik: %2$s. Hari dengan klik: %3$s. Rata-rata per hari klik: %4$s.','No click data available for this period.'=>'Data klik tidak tersedia untuk periode ini.','click'=>'klik','clicks'=>'klik','Each bar shows total clicks for one day.'=>'Setiap batang menunjukkan total klik untuk satu hari.','Each bar shows total clicks for a 7-day period.'=>'Setiap batang menunjukkan total klik untuk periode 7 hari.','Each bar shows total clicks for one month.'=>'Setiap batang menunjukkan total klik untuk satu bulan.','Each bar shows total clicks for one year.'=>'Setiap batang menunjukkan total klik untuk satu tahun.','Yesterday'=>'Kemarin','Last 30 Days'=>'30 Hari Terakhir','This Month'=>'Bulan Ini','Last Month'=>'Bulan Lalu','This Year'=>'Tahun Ini','Last 2 Years'=>'2 Tahun Terakhir','Custom Range'=>'Rentang Kustom','All Time'=>'Sepanjang Waktu','From:'=>'Dari:','To:'=>'Ke:','Days With Clicks'=>'Hari Dengan Klik','Avg. per Click Day'=>'Rata-rata per Klik per Hari','Clicks Over Time'=>'Klik Selama Waktu','QR code for this shortlink'=>'Kode QR untuk shortlink ini','Suggested Label from target URL'=>'Label yang Disarankan dari URL target','Suggested Notes from target URL'=>'Catatan yang Disarankan dari URL target','Overwrite label?'=>'Tulis ulang label?','Overwrite notes?'=>'Tulis ulang catatan?','Yes'=>'Ya','No'=>'Tidak']];